initialize row of length n+1 with all 1s  
for i from 1 to n:  
 for j from i‑1 down to 1:  
  row[j] = row[j] + row[j‑1]  
return row

code.cpp:
class Solution {
public:
    vector<int> getRow(int rowIndex) {
        vector<int> row(rowIndex + 1, 1);
        for (int i = 1; i <= rowIndex; ++i) {
            for (int j = i - 1; j > 0; --j) {
                row[j] += row[j - 1];
            }
        }
        return row;
    }
};
